operations.exampleQuery:
mutation createToken {
  createToken(
    login: "<login>"
    password: "<senha>"
  ) {
    token
  }
}

mutation saveInventories {
  saveInventories(
    industryCode: "FAB"
    inventories: [
      {
        referenceDate: "2026-08-20"
        customerCode: "00000000000000"
        customerType: WHOLESALER
        productCode: "7891106001946"
        supply: 400
        operationType: INSERT
      }
    ]
  ) {
    status
    loadId
    message
  }
}
